    def from_mrk(cls, string: str, auth_control=True, delete_subfield_zero=True):
        self = cls()

        for line in filter(None, string.split('\n')):
            match = re.match(r'=(\w{3})  (.*)', line)            
            tag, rest = match.group(1), match.group(2)
            if tag == 'LDR': tag = '000'

            if tag[:2] == '00':
